def run():
    lock=verify();s=read(OUT/'SUMMARY.json');rows=read(OUT/'ROWS.json');prior=read(S0/'SUMMARY.json');state=load(OUT/'PARAMETER_SUPPORT.pt');cfg=read(OUT/'PARAMETER_SUPPORT.json');assert sha(OUT/'PARAMETER_SUPPORT.pt')==cfg['sha256']
    flat=lambda x:np.concatenate([v.double().numpy().ravel() for v in x.values()]);center=flat(state['center']);basis=state['basis'].numpy();np.testing.assert_allclose(basis@basis.T,np.eye(4),atol=1e-12,rtol=0)
    for k in range(4):
        for sign,j in [(1,1+2*k),(-1,2+2*k)]:np.testing.assert_allclose(flat(state['states'][j])-center,sign*cfg['radius']*basis[k],atol=1.5e-7,rtol=0)
